var fieldsContextKey contextKey

var globalFields struct {
	sync.RWMutex
	fields      []LogField
	serviceName string
}

type contextKey struct{}

// ContextWithFields returns a new context with the given fields.
func ContextWithFields(ctx context.Context, fields ...LogField) context.Context {
	if val := ctx.Value(fieldsContextKey); val != nil {
		if arr, ok := val.([]LogField); ok {
			return context.WithValue(ctx, fieldsContextKey, append(arr, fields...))
		}
	}

	return context.WithValue(ctx, fieldsContextKey, fields)
}

// WithFields returns a new logger with the given fields.
// deprecated: use ContextWithFields instead.
func WithFields(ctx context.Context, fields ...LogField) context.Context {
	return ContextWithFields(ctx, fields...)
}

// SetGlobalFields replaces the fields added to every log entry.
// Fields set on an individual log call take precedence over global fields with the same key.
func SetGlobalFields(fields ...LogField) {
	globalFields.Lock()
	globalFields.fields = append([]LogField(nil), fields...)
	globalFields.Unlock()
}

// AddGlobalField adds a field to every log entry.
func AddGlobalField(field LogField) {
	AddGlobalFields(field)
}

// AddGlobalFields appends fields that will be included in every log entry.
func AddGlobalFields(fields ...LogField) {
	globalFields.Lock()
	globalFields.fields = append(globalFields.fields, fields...)
	globalFields.Unlock()
}

func getGlobalFields() []LogField {
	globalFields.RLock()
	defer globalFields.RUnlock()

	if len(globalFields.serviceName) == 0 && len(globalFields.fields) == 0 {
		return nil
	}

	fields := make([]LogField, 0, len(globalFields.fields)+1)
	if len(globalFields.serviceName) > 0 {
		fields = append(fields, Field("serviceName", globalFields.serviceName))
	}
	return append(fields, globalFields.fields...)
}

func setGlobalServiceName(name string) {
	globalFields.Lock()
	globalFields.serviceName = name
	globalFields.Unlock()
}

